mapper.select:
select u.id, u.day_matter_id, u.group_id, m.day_name, g.group_name, g.group_code from mes_msg_day_matter_group u left join mes_msg_day_matter m on u.day_matter_id = m.id and m.deleted_flag = '0' left join mes_msg_group g on u.group_id = g.id and g.deleted_flag = '0'
u.deleted_flag = '0'
and u.id = #{param.id}
and u.group_id = #{param.groupId}
and u.day_matter_id = #{param.dayMatterId}
order by u.update_time desc
